DO $design_catalog_migration$
DECLARE
  entries jsonb := $design_catalog_a883b5753d766431$[{"manifest":{"slug":"image-layer-separation","name":"图片分层与原生图层","description":"区分原生设计图层编辑与扁平图片分层，为拆分背景、主体、文字等提供当前可执行路径；不将 RGBA 位图拆解冒充原始 PSD 或可编辑字体。","version":"2.2.0","category":"design","iconName":"layers","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"guidance","intents":["image-layer-separation","layer-grouping","rgba-layer-review"],"outputKinds":["operation-guidance","native-layer-edit"],"requiredTools":[],"optionalTools":["inspect_canvas","inspect_design","get_design_objects","manipulate_design","verify_design_result"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]}],"limitations":["扁平图支持工具栏大模型流程：2–4个指定透明元素及修补底图，共3–5次生成，默认Low+1K；Agent仍没有直接split_layers工具。","已有原生设计图层可在实际工具和目标权限允许时编辑；位图拆分不能恢复原始 PSD、字体或被遮挡像素。","专用分层服务和旧本地处理独立保留，不在失败时隐式回退；本包不下载模型或安装外部服务。","本包是 Loomic 原创流程，官方模型卡不是本项目效果实测，不能声称分层结果已经通过视觉验收。"],"examples":["把这张扁平海报拆成背景、产品和文字层。","只将画板里现有产品图层与标题分组，其他内容不动。"],"sources":[{"title":"Qwen-Image-Layered 官方模型卡","url":"https://huggingface.co/Qwen/Qwen-Image-Layered","license":"Apache-2.0","relation":"inspired-by"}],"composition":{"role":"domain","stages":["design"]}}}},"content":"---\nname: image-layer-separation\ndescription: 区分原生设计图层编辑与扁平图片分层，为拆分背景、主体、文字等提供当前可执行路径；不将 RGBA 位图拆解冒充原始 PSD 或可编辑字体。\nmetadata:\n  author: loomic\n  version: \"2.2.0\"\n---\n\n# 图片分层与原生图层\n\n先确认用户指的是已有画板中的真实对象，还是单张扁平图片。对象 ID、源资产与当前目标从实际工具读取，不把截图中看起来独立的元素当作已有图层。\n\n对原生设计，inspect_design 与 get_design_objects 可以读取真实层级，再使用 manipulate_design 在用户指定范围内修改、分组或调整层序。保留字体和其他对象；单纯移动某一层不需要先拆图或重设计。\n\n对扁平图片，选中原图使用图片工具栏的「图层拆分」。大模型流程按用户指定的 2–4 个元素分别生成透明 PNG，再移除这些元素、修补完整底图，默认 Low + 1K。元素名称应具体，例如“左侧蛇形角色”“右侧人物”“所有标题文字”“前景金币”。未选择的元素保留在底图；这不是自动发现所有潜在图层。界面提交一项拆分任务，但内部需要元素数量加一次背景生成，按总量计费。透明素材会按有效像素裁成小图，并记录相对位置，原图保持不变。\n\n当前 Agent 的 generate_image/edit_image 工具没有直接 split_layers 操作。不要发送不存在的工具参数，也不要用一次普通生图冒充多层拆分；通过真实工具栏流程执行，不声称已从 PNG 恢复原始字体、遮挡内容或 PSD。大模型可能重绘细节，底图修补是推测；要求逐像素无损时应说明限制。\n\n此技能仍为工具栏操作与验收指导，不会安装模型或服务。阅读 [分层验收与引擎边界](references/workflow.md) 检查真实结果。专用分层和旧本地处理属于独立入口，不应在失败时悄悄互相替代。\n\n只要求建议或检查时不修改对象。执行仍受当前工具、画板目标锁、用户纠正、权限和费用确认约束；技能说明不增加这些权限。\n","files":[{"file_path":"references/workflow.md","content":"# 分层验收与引擎边界\n\n## 验证实际拆分结果\n\n保留原图，记录每层实际尺寸、透明范围、相对位置和层序。将所有结果层按原位置合成后与原图比较，检查主体是否丢失、边缘是否被切碎、阴影和孔洞是否合理，以及重复背景是否影响合成。工具执行成功不等于视觉结果合格；未得到真实结果时只能说明验收方法。\n\n图片里的文字分到透明 PNG 仍是位图，不代表可以改文字或字体。遮挡区域的补全是推测，不能宣称恢复了原始隐藏像素。用户明确要求原始可编辑 PSD、原字体文字或无损恢复时应解释输入限制，并建议提供原始设计文件。\n\n## 当前大模型路径\n\n选中单张已有图片，输入 2–4 个互不重叠的元素说明。每层使用同一原图作为编辑来源，仅保留指定元素，输出透明 PNG；底图移除全部指定元素并补全背景。一次任务共生成 3–5 张图，默认 Low + 1K，不因为分层自动提高质量或分辨率。\n\n先核对每个透明层是否有非空主体和透明像素，再检查裁切是否切断阴影、细线或发丝。背景应检查指定元素是否被移除、填补区域有无明显重复纹理或残字。透明像素校验不等于视觉合格；任何一层失败都不能把任务描述为全部完成。重试应复用已经归档的分层结果，不能再次生成已成功的层。\n\n## 专用引擎\n\n[Qwen-Image-Layered 官方模型卡](https://huggingface.co/Qwen/Qwen-Image-Layered) 提供 RGBA 图层拆分的示例。项目保留专用服务入口，其可用性以实际配置检查为准，不将论文指标描述为本项目实测结果。\n\n接入专用引擎应单独评估部署资源、许可、延迟和样本重合成效果，明确用户授权后再实施。本技能不下载模型、不调用外部演示站、不安装 ComfyUI 工作流，也不自动升级本地拆分工具。\n","mime_type":"text/markdown"}]}]$design_catalog_a883b5753d766431$::jsonb;
  entry jsonb;
  file_entry jsonb;
  target_id uuid;
BEGIN
  -- Lock existing rows before ownership checks. A competing slug INSERT is
  -- checked again by the guarded UPSERT below, so it cannot grant ownership.
  PERFORM 1 FROM public.skills AS s
    WHERE s.slug IN (SELECT item->'manifest'->>'slug' FROM jsonb_array_elements(entries) AS item)
    ORDER BY s.slug FOR UPDATE;
  IF EXISTS (
    SELECT 1 FROM public.skills AS s
    WHERE s.slug IN (SELECT item->'manifest'->>'slug' FROM jsonb_array_elements(entries) AS item)
      AND (s.source IS DISTINCT FROM 'system' OR s.created_by IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'Design skill catalog conflicts with a non-owned skill; nothing was changed';
  END IF;

  FOR entry IN SELECT value FROM jsonb_array_elements(entries) LOOP
    target_id := NULL;
    INSERT INTO public.skills AS owned (slug, name, description, author, version, license, category, icon_name, source, skill_content, metadata, is_featured)
    VALUES (entry->'manifest'->>'slug', entry->'manifest'->>'name', entry->'manifest'->>'description', 'Loomic',
      entry->'manifest'->>'version', entry->'manifest'->>'license', entry->'manifest'->>'category',
      entry->'manifest'->>'iconName', 'system', entry->>'content', entry->'manifest'->'metadata', true)
    ON CONFLICT (slug) DO UPDATE SET
      name = EXCLUDED.name, description = EXCLUDED.description, author = EXCLUDED.author,
      version = EXCLUDED.version, license = EXCLUDED.license, category = EXCLUDED.category,
      icon_name = EXCLUDED.icon_name, skill_content = EXCLUDED.skill_content,
      metadata = COALESCE(owned.metadata, '{}'::jsonb) || EXCLUDED.metadata, updated_at = now()
    WHERE owned.source = 'system' AND owned.created_by IS NULL
    RETURNING id INTO target_id;
    IF target_id IS NULL THEN
      RAISE EXCEPTION 'Design skill ownership changed concurrently; nothing was changed';
    END IF;
    FOR file_entry IN SELECT value FROM jsonb_array_elements(entry->'files') LOOP
      INSERT INTO public.skill_files (skill_id, file_path, content, mime_type)
      VALUES (target_id, file_entry->>'file_path', file_entry->>'content', file_entry->>'mime_type')
      ON CONFLICT (skill_id, file_path) DO UPDATE SET
        content = EXCLUDED.content, mime_type = EXCLUDED.mime_type, updated_at = now();
    END LOOP;
  END LOOP;
END;
$design_catalog_migration$;
